 81→mod tests {
 82→    use super::*;
 83→    use crate::ui::PromptType;
 84→
 85→    fn make_prompt(key: &str, default: Option<&str>) -> Prompt {
 86→        Prompt {
 87→            key: key.to_string(),
 88→            question: "Test question?".to_string(),
 89→            prompt_type: PromptType::Input,
 90→            default: default.map(String::from),
 91→        }
 92→    }
 93→
 94→    #[test]
 95→    fn non_interactive_uses_defaults() {
 96→        let prompts = vec![make_prompt("key1", Some("default_value"))];
 97→        let env = HashMap::new();
 98→
 99→        let values = PreflightCollector::collect_non_interactive(&prompts, &env).unwrap();
100→
101→        assert_eq!(values.get("key1"), Some(&"default_value".to_string()));
102→    }
103→
104→    #[test]
105→    fn non_interactive_uses_env_override() {
106→        let prompts = vec![make_prompt("key1", Some("default"))];
107→        let mut env = HashMap::new();
108→        env.insert("BIVVY_PROMPT_KEY1".to_string(), "override".to_string());
109→
110→        let values = PreflightCollector::collect_non_interactive(&prompts, &env).unwrap();
