mod tests {
    use super::*;

    fn make_prompt(key: &str, prompt_type: PromptType, default: Option<&str>) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: "Test question?".to_string(),
            prompt_type,
            default: default.map(String::from),
        }
    }

    #[test]
    fn prompt_creation() {
        let prompt = make_prompt("test", PromptType::Input, Some("default"));
        assert_eq!(prompt.key, "test");
        assert_eq!(prompt.default, Some("default".to_string()));
    }

    #[test]
    fn prompt_type_confirm_creation() {
        let prompt = make_prompt("confirm", PromptType::Confirm, None);
        assert!(matches!(prompt.prompt_type, PromptType::Confirm));
    }

    #[test]
    fn prompt_type_select_with_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select",
            PromptType::Select {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::Select { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 2);
            assert_eq!(stored[0].value, "a");
        } else {
            panic!("Expected Select variant");
        }
    }

    #[test]
    fn prompt_type_multiselect_with_options() {
        let options = vec![PromptOption {
            label: "Feature 1".to_string(),
            value: "f1".to_string(),
        }];
        let prompt = make_prompt(
            "multi",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::MultiSelect { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 1);
        } else {
            panic!("Expected MultiSelect variant");
        }
    }

    #[test]
    fn is_yes_no_returns_true_for_yes_no_options() {
        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_true_regardless_of_order() {
        let options = vec![
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_other_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    fn yes_no_options() -> Vec<PromptOption> {
        vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ]
    }

    #[test]
    fn yes_no_key_action_ctrl_d_returns_error() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::Char('\x04'), &options, &mut sel);
        assert!(result.is_err());
    }

    #[test]
    fn yes_no_key_action_y_selects_yes() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::Char('y'), &options, &mut sel);
        assert_eq!(result.unwrap(), Some(0));
    }

    #[test]
    fn yes_no_key_action_n_selects_no() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::Char('n'), &options, &mut sel);
        assert_eq!(result.unwrap(), Some(1));
    }

    #[test]
    fn yes_no_key_action_enter_selects_current() {
        let options = yes_no_options();
        let mut sel = 1;
        let result = yes_no_key_action(&Key::Enter, &options, &mut sel);
        assert_eq!(result.unwrap(), Some(1));
    }

    #[test]
    fn yes_no_key_action_arrow_down_advances() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::ArrowDown, &options, &mut sel);
        assert_eq!(result.unwrap(), None);
        assert_eq!(sel, 1);
    }

    #[test]
    fn yes_no_key_action_arrow_down_wraps() {
        let options = yes_no_options();
        let mut sel = 1;
        let result = yes_no_key_action(&Key::ArrowDown, &options, &mut sel);
        assert_eq!(result.unwrap(), None);
        assert_eq!(sel, 0);
    }

    #[test]
    fn yes_no_key_action_arrow_up_wraps() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::ArrowUp, &options, &mut sel);
        assert_eq!(result.unwrap(), None);
        assert_eq!(sel, 1);
    }

    #[test]
    fn yes_no_key_action_unknown_key_returns_none() {
        let options = yes_no_options();
        let mut sel = 0;
        let result = yes_no_key_action(&Key::Char('x'), &options, &mut sel);
        assert_eq!(result.unwrap(), None);
        assert_eq!(sel, 0);
    }
}

