/// Determine the action for a key press in the yes/no prompt.
///
/// Returns `Ok(Some(idx))` to select the option at `idx`, `Ok(None)` to
/// continue the input loop, or `Err` for abort signals like Ctrl+D.
fn yes_no_key_action(
    key: &Key,
    options: &[PromptOption],
    sel: &mut usize,
) -> Result<Option<usize>> {
    match key {
        Key::Char('y') | Key::Char('Y') => {
            Ok(options.iter().position(|o| o.value == "yes"))
        }
        Key::Char('n') | Key::Char('N') => {
            Ok(options.iter().position(|o| o.value == "no"))
        }
        Key::Enter | Key::Char(' ') => Ok(Some(*sel)),
        Key::Char('\x04') => Err(BivvyError::Io(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "Aborted (Ctrl+D)",
        ))),
        Key::ArrowDown | Key::Tab | Key::Char('j') => {
            *sel = (*sel + 1) % options.len();
            Ok(None)
        }
        Key::ArrowUp | Key::BackTab | Key::Char('k') => {
            *sel = (*sel + options.len() - 1) % options.len();
            Ok(None)
        }
        _ => Ok(None),
    }
}

/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
///
/// Renders options below the prompt question, indented to align with
/// the step name. Supports arrow keys, j/k, Enter/Space, and y/n.
/// Ctrl+D aborts the prompt and returns an error.
fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    // Calculate indent: measure the visible width of the question text
    // to find where `[n/t] ` ends. We use a heuristic: find the first `]`
    // and add 2 for `] `.
    let indent = measure_text_width(&prompt.question)
        .min(prompt.question.find(']').map(|i| i + 2).unwrap_or(6));

    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    let result = prompt_yes_no_loop(prompt, options, term, default_idx, indent);

    // Always restore cursor, even on error
    term.show_cursor().ok();

    result
}

